@Test
public void checkLoadAll_4_oe()
{

    count.decrementAndGet();
    cache.loadAll(new HashSet<>(asList("a", "b")), true, null);
    int retries = 100;
    while (retries-- > 0 && count.get() != 2)
    {
        try
        {
            Thread.sleep(20);
        }
        catch (final InterruptedException e)
        {
            Thread.interrupted();
        }
    }
    assertEquals("a", cache.get("a"));
}

